/** Registra a composição atual da arena sem modificar código, física ou artes de produção. */
import fs from 'node:fs/promises';
import assert from 'node:assert/strict';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const cdp='http://127.0.0.1:9222',host='http://127.0.0.1:3000';
const tab=await(await fetch(cdp+'/json/new?'+encodeURIComponent(host),{method:'PUT'})).json();
const ws=new WebSocket(tab.webSocketDebuggerUrl);await new Promise(r=>ws.addEventListener('open',r,{once:true}));
let sequence=0;const pending=new Map();
ws.addEventListener('message',e=>{const m=JSON.parse(e.data);const p=pending.get(m.id);if(p){pending.delete(m.id);m.error?p.reject(Error(m.error.message)):p.resolve(m.result);}});
const send=(method,params={})=>new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
const run=async expression=>{const r=await send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.exceptionDetails)throw Error(r.exceptionDetails.exception?.description||r.exceptionDetails.text);return r.result.value;};
const until=async(expression)=>{const end=Date.now()+30000;while(Date.now()<end){if(await run(expression))return;await sleep(80);}throw Error('Não ficou pronto: '+expression);};
const folder='docs/diario-ia/qa-resultados/saida-arena';await fs.mkdir(folder,{recursive:true});
async function capture(name,data=null){
 const bytes=data?Buffer.from(data.split(',')[1],'base64'):Buffer.from((await send('Page.captureScreenshot',{format:'png'})).data,'base64');
 await fs.writeFile(folder+'/'+name+'.png',bytes);await fs.writeFile('/tmp/legendgirl-'+name+'.png',bytes);
}

try{
 await send('Page.enable');await send('Runtime.enable');
 for(const [name,width,height,mobile] of [['desktop',1440,900,false],['retrato',390,844,true],['paisagem',844,390,true]]) {
  await send('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});
  await send('Page.navigate',{url:host});await until('Boolean(window.game)');await run('game.assetsReady');
  assert.equal(await run('location.origin'),host);assert.ok(!host.endsWith(':3000'));
  await run(`game.startDebugPhase('arena');game.setPaused(true);document.getElementById('start-overlay').style.display='none'`);
  await run(`Promise.all([game.state.toyRoomInstance.instance.arena.readyPromise,game.state.toyRoomInstance.instance.battle.readyPromise])`);
  const result=await run(`(()=>{window.r=game.state.toyRoomInstance.instance;r.mobilePresentation=${mobile};r.isTouchDevice=${mobile};r.isInputEnabled=()=>true;r.arena.state.status='COMBAT';r.battle.activate();const s=r.battle.state;s.index=3;r.battle.spawn();s.transition=null;s.enemy.hp=1;s.enemy.x=650;s.enemy.enrage=true;s.enemy.enrageShown=true;r.player.x=430;r.story.state.swordEquipped=true;r.introAlpha=0;r.introBannerTimer=0;const attacked=r.arena.attack();let frames=0;while(r.arena.state.status==='COMBAT'&&frames<20){r.arena.update(1);frames++;}return {attacked,frames,status:r.arena.state.status,destination:r.arena.state.destination,hp:s.enemy.hp,transition:s.transition};})()`);
  assert.equal(result.attacked,true);assert.ok(result.frames<=12);assert.equal(result.status,'RETURNING');assert.equal(result.destination,'CHASE');assert.equal(result.hp,0);assert.equal(result.transition,null);
  assert.equal(await run(`(()=>{const text=[];const fill=r.ctx.fillText;r.ctx.fillText=function(t,...args){text.push(t);return fill.call(this,t,...args);};try{r.render();}finally{r.ctx.fillText=fill;}return text.length;})()`),0,'Sem texto no início da saída');
  await run('for(let i=0;i<30;i++)r.arena.update(1)');
  await until('Boolean(r.chase?.ready)');
  assert.deepEqual(await run(`({stage:r.chase.state.stage,age:r.chase.state.age,completed:r.story.state.arenaCompleted,status:r.arena.state.status})`),{stage:'BEAR_DOWN',age:0,completed:true,status:'COMPLETE'});
  const first=await run(`(()=>{r.chase.enabled=()=>true;r.chase.setPaused(false);while(r.chase.handoffFade>0)r.chase.update(1);const text=[];const fill=r.ctx.fillText;r.ctx.fillText=function(t,...args){text.push(t);return fill.call(this,t,...args);};try{r.render();}finally{r.ctx.fillText=fill;}return {stage:r.chase.state.stage,text};})()`);
  assert.equal(first.stage,'BEAR_DOWN');assert.deepEqual(first.text,[],'Primeira imagem sem legenda ou controles sobrepostos');
  await capture('saida-direta-'+name);
  console.log('APROVADO: '+name+', último golpe → saída em '+result.frames+' quadros → BEAR_DOWN, sem textos.');
 }
}finally{ws.close();await fetch(cdp+'/json/close/'+tab.id);}
